            const [events, cost] = await Promise.all([
                fetchSessionEvents({
                    baseUrl: target.agentUrl,
                    sessionId: resolved,
                    auth,
                    fetchImpl: options.fetchImpl,
                }),
                fetchSessionCost({
                    baseUrl: target.agentUrl,
                    sessionId: resolved,
                    auth,
                    fetchImpl: options.fetchImpl,
                }),
            ]);
